// Reference skeletons for the follow-along mode (generated by scripts/build-follow-references.mjs) and their drawing.
import type { MotionView } from "../drill/continuousMotion";

export interface ReferenceClip { source: string; fps: number; moveMs: [number, number]; frames: (number | null)[][] }
export interface ReferenceSet { joints: string[]; clips: Record<string, ReferenceClip> }
export type Point = [number, number];
/** Joint name -> position in torso lengths from the reference's first-frame hip centre (image axes, y down). */
export type ReferencePose = Record<string, Point>;

let cache: Promise<ReferenceSet> | null = null;
/** Lazily loaded so the main bundle does not carry the reference animations. */
export function loadReferences(): Promise<ReferenceSet> {
  cache ??= import("./referenceClips.json").then(m => (m.default ?? m) as unknown as ReferenceSet);
  return cache;
}

export const referenceKey = (view: MotionView, drill: string) => `${view}:${drill}`;
export const clipDurationMs = (clip: ReferenceClip) => (clip.frames.length - 1) * 1000 / clip.fps;

/** Reference pose at `elapsedMs` of playback at `tempo` (1 = original speed), looping, linearly interpolated. */
export function poseAt(set: ReferenceSet, clip: ReferenceClip, elapsedMs: number, tempo = 1): ReferencePose {
  const duration = clipDurationMs(clip);
  const t = duration > 0 ? ((elapsedMs * tempo) % duration + duration) % duration : 0;
  const f = t / 1000 * clip.fps, i = Math.min(clip.frames.length - 1, Math.floor(f)), r = f - i;
  const a = clip.frames[i], b = clip.frames[Math.min(clip.frames.length - 1, i + 1)];
  const pose: ReferencePose = {};
  set.joints.forEach((name, k) => {
    const ax = a[2 * k], ay = a[2 * k + 1], bx = b[2 * k], by = b[2 * k + 1];
    if (ax === null || ay === null) return;
    const x = bx === null ? ax : ax + (bx - ax) * r, y = by === null ? ay : ay + (by - ay) * r;
    pose[name] = [x / 1000, y / 1000];
  });
  return pose;
}

/** Fraction (0..1) of the loop elapsed, for the progress bar. */
export function loopProgress(clip: ReferenceClip, elapsedMs: number, tempo = 1): number {
  const duration = clipDurationMs(clip);
  return duration > 0 ? (((elapsedMs * tempo) % duration) + duration) % duration / duration : 0;
}

export const EDGES: Array<[string, string]> = [
  ["left_shoulder", "right_shoulder"], ["left_shoulder", "left_hip"], ["right_shoulder", "right_hip"],
  ["left_hip", "right_hip"], ["left_shoulder", "left_elbow"], ["left_elbow", "left_wrist"],
  ["right_shoulder", "right_elbow"], ["right_elbow", "right_wrist"], ["left_hip", "left_knee"],
  ["left_knee", "left_ankle"], ["right_hip", "right_knee"], ["right_knee", "right_ankle"],
  ["left_ankle", "left_foot_index"], ["right_ankle", "right_foot_index"],
];

/** Place a reference pose on screen: `origin` (px) is where the reference hip centre goes, `scale` px per torso length. */
export function placePose(pose: ReferencePose, origin: Point, scale: number, flipX = false): Record<string, Point> {
  const out: Record<string, Point> = {};
  for (const [name, [x, y]] of Object.entries(pose)) out[name] = [origin[0] + (flipX ? -x : x) * scale, origin[1] + y * scale];
  return out;
}

export interface GhostStyle { glow: string; line: string; width: number; joints: string }
export const REFERENCE_STYLE: GhostStyle = { glow: "rgba(177, 104, 255, 0.9)", line: "rgba(255, 222, 128, 0.98)", width: 3, joints: "rgba(255, 225, 136, 0.96)" };

export function drawSkeleton(ctx: CanvasRenderingContext2D, points: Record<string, Point>, style: GhostStyle) {
  ctx.save();
  ctx.lineCap = "round"; ctx.lineJoin = "round";
  ctx.shadowColor = style.glow; ctx.shadowBlur = 14;
  ctx.strokeStyle = style.glow.replace(/[\d.]+\)$/, "0.55)"); ctx.lineWidth = style.width * 2.8;
  stroke(ctx, points);
  ctx.shadowBlur = 4; ctx.strokeStyle = style.line; ctx.lineWidth = style.width;
  stroke(ctx, points);
  ctx.shadowBlur = 0; ctx.fillStyle = style.joints;
  for (const name of ["left_wrist", "right_wrist", "left_elbow", "right_elbow", "left_knee", "right_knee", "left_ankle", "right_ankle"]) {
    const p = points[name]; if (!p) continue;
    ctx.beginPath(); ctx.arc(p[0], p[1], style.width * 1.7, 0, Math.PI * 2); ctx.fill();
  }
  const nose = points.nose, ls = points.left_shoulder, rs = points.right_shoulder;
  if (nose && ls && rs) {
    const r = Math.hypot(ls[0] - rs[0], ls[1] - rs[1]) * 0.28 + style.width * 2;
    ctx.strokeStyle = style.line; ctx.lineWidth = style.width;
    ctx.beginPath(); ctx.arc(nose[0], nose[1], r, 0, Math.PI * 2); ctx.stroke();
  }
  ctx.restore();
}

function stroke(ctx: CanvasRenderingContext2D, points: Record<string, Point>) {
  ctx.beginPath();
  for (const [a, b] of EDGES) {
    const p = points[a], q = points[b];
    if (!p || !q) continue;
    ctx.moveTo(p[0], p[1]); ctx.lineTo(q[0], q[1]);
  }
  ctx.stroke();
}
